+      autoComplete="new-password"
+      $labelPosition="horizontal"
+      labelColor="white"
+      onChange={(e) => setConfirmPassword(e.target.value)}
+      placeholder="영문 + 숫자 + 특수문자 1개 포함 8자리 이상"
+      isPasswordField={true}
+      errorMessage={confirmPwdError ?? undefined}
+    />
+  )}
+
+
+    <CommonTextField
+      radius="0"
+      value={name}
+      label="* 이름"
+      $labelPosition="horizontal"
+      labelColor="white"
+      onChange={(e) => setName(e.target.value)}
+      placeholder="이름을 입력하세요"
+      errorMessage={nameError ?? undefined}
+    />
+    <CommonTextField
+      radius="0"
+      value={email}
+      label="* 이메일"
+      $labelPosition="horizontal"
+      labelColor="white"
+      onChange={(e) => setEmail(e.target.value)}
+      placeholder="이메일 형식으로 입력하세요"
+      errorMessage={emailError ?? undefined}
+    />
+    <CommonTextField
+      radius="0"
+      value={cellphone}
+      label="* 연락처"
+      $labelPosition="horizontal"
+      labelColor="white"
+      onChange={(e) => {
+        const input = e.target.value;
+        if (/^\d*$/.test(input) && input.length <= 11) {
+          setCellphone(input);
+        }
+      }}
+      placeholder="- 제외 하고 입력하세요"
+      errorMessage={cellphoneError ?? undefined}
+    />
+
+
+  {/* 수정 모드일 때: 이메일 수신 Switch 위에 비밀번호 변경 버튼 */}
+  {selectedUser && (
+<div>
+{/* <SwitchLabel>비밀번호 변경</SwitchLabel> */}
+    <SwitchRow>
+      <PwdChangeButton
+  style={{ width: 'auto', padding: '0px 16px', fontSize: '14px' }}
+  onClick={() => setIsPwdChangeOpen(true)}
+>
+  비밀번호 변경
+</PwdChangeButton>
+
+    </SwitchRow></div>
+  )}
+
+
+    {/* <SwitchInput
+      label="이메일 수신"
+      value={emailYn}
+      onChange={setEmailYn}
+      $labelPosition="horizontal"
+      labelColor="white"
+    />
+
+    <SwitchInput
+      label="SMS 수신"
+      value={smsYn}
+      onChange={setSmsYn}
+      $labelPosition="horizontal"
+      labelColor="white"
+    /> */}
+
+    <TextArea
+      radius="0"
+      multiline
+      minLines={4}
+      maxLines={10}
+      height="200px"
+      value={description}
+      label="비고"
+      $labelPosition="horizontal"
+      labelColor="white"
+      onChange={(e) => setDescription(e.target.value)}
+      placeholder="비고를 입력하세요"
+      height="200px"
+    />
+  </FormContainer>
+</CmsPopup>
+
+<PasswordPopup
+  adminId={userId}
+  isOpen={isPwdChangeOpen}
+  onClose={() => setIsPwdChangeOpen(false)}
+/>
+
+
+    </>
